     1|/**
     2| * IVX Task Execution State Machine
     3| *
     4| * Owner mandate 2026-07-20 Phase 1: replace the simplified task status logic
     5| * with a real 17-state state machine that enforces legal transitions and the
     6| * owner's completion rules.
     7| *
     8| * Rules (enforced in canTransition + assertCanTransition):
     9| *   - DEPLOYED means only that a deployment occurred.
    10| *   - VERIFIED means the requested acceptance tests passed.
    11| *   - A task cannot become VERIFIED from /health alone.
    12| *   - A development task cannot become VERIFIED when no code changed unless the
    13| *     system proves that configuration, data, infrastructure, or an external
    14| *     dependency was the actual cause.
    15| *   - If no work was completed, status must be BLOCKED, FAILED, or
    16| *     NO_CHANGE_REQUIRED.
    17| *   - Never display "development completed" when the code diff is empty.
    18| *
    19| * This module is intentionally runtime-free and does NOT import worker types,
    20| * to avoid circular dependencies.
    21| */
    22|
    23|export const IVX_TASK_STATE_MACHINE_MARKER = 'ivx-task-state-machine-2026-07-21';
    24|
    25|export type IVXTaskState =
    26|  | 'RECEIVED'
    27|  | 'ANALYZING'
    28|  | 'REPRODUCING'
    29|  | 'ROOT_CAUSE_IDENTIFIED'
    30|  | 'IMPLEMENTING'
    31|  | 'CODE_CHANGED'
    32|  | 'TESTING'
    33|  | 'QA_REQUIRED'
    34|  | 'QA_IN_PROGRESS'
    35|  | 'READY_TO_DEPLOY'
    36|  | 'DEPLOYING'
    37|  | 'DEPLOYED'
    38|  | 'PRODUCTION_VERIFYING'
    39|  | 'VERIFIED'
    40|  | 'COMPLETED'
    41|  | 'BLOCKED'
    42|  | 'FAILED'
    43|  | 'NO_CHANGE_REQUIRED';
    44|
    45|export const ALL_TASK_STATES: readonly IVXTaskState[] = [
    46|  'RECEIVED',
    47|  'ANALYZING',
    48|  'REPRODUCING',
    49|  'ROOT_CAUSE_IDENTIFIED',
    50|  'IMPLEMENTING',
    51|  'CODE_CHANGED',
    52|  'TESTING',
    53|  'QA_REQUIRED',
    54|  'QA_IN_PROGRESS',
    55|  'READY_TO_DEPLOY',
    56|  'DEPLOYING',
    57|  'DEPLOYED',
    58|  'PRODUCTION_VERIFYING',
    59|  'VERIFIED',
    60|  'COMPLETED',
    61|  'BLOCKED',
    62|  'FAILED',
    63|  'NO_CHANGE_REQUIRED',
    64|] as const;
    65|
    66|export const TERMINAL_TASK_STATES: ReadonlySet<IVXTaskState> = new Set([
    67|  'VERIFIED',
    68|  'COMPLETED',
    69|  'BLOCKED',
    70|  'FAILED',
    71|  'NO_CHANGE_REQUIRED',
    72|]);
    73|
    74|/**
    75| * Task types that drive the terminal-state completion rules. The guard uses
    76| * these to decide which gates are required for COMPLETED vs VERIFIED.
    77| * Owner mandate 2026-07-21: a task must NEVER finish FAILED when its requested
    78| * gates all succeeded; deploy/feature-verification are only required when
    79| * deployment was explicitly requested.
    80| */
    81|export type IVXGuardTaskType =
    82|  | 'CODE_FIX'
    83|  | 'FEATURE'
    84|  | 'UI_FIX'
    85|  | 'DATA_FIX'
    86|  | 'INVESTIGATION'
    87|  | 'QA_ONLY'
    88|  | 'DEPLOY_ONLY'
    89|  | 'FACTORY';
    90|
    91|/**
    92| * Legal forward transitions. A task may not skip from RECEIVED straight to
    93| * DEPLOYED or VERIFIED — it must walk the senior-developer loop.
    94| */
    95|const LEGAL_TRANSITIONS: ReadonlyMap<IVXTaskState, ReadonlySet<IVXTaskState>> = new Map([
    96|  ['RECEIVED', new Set(['ANALYZING', 'COMPLETED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    97|  ['ANALYZING', new Set(['REPRODUCING', 'ROOT_CAUSE_IDENTIFIED', 'COMPLETED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    98|  ['REPRODUCING', new Set(['ROOT_CAUSE_IDENTIFIED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    99|  ['ROOT_CAUSE_IDENTIFIED', new Set(['IMPLEMENTING', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
   100|  ['IMPLEMENTING', new Set(['CODE_CHANGED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
   101|  ['CODE_CHANGED', new Set(['TESTING', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   102|  ['TESTING', new Set(['QA_REQUIRED', 'READY_TO_DEPLOY', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   103|  ['QA_REQUIRED', new Set(['QA_IN_PROGRESS', 'BLOCKED', 'FAILED'])],
   104|  ['QA_IN_PROGRESS', new Set(['READY_TO_DEPLOY', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   105|  ['READY_TO_DEPLOY', new Set(['DEPLOYING', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   106|  ['DEPLOYING', new Set(['DEPLOYED', 'BLOCKED', 'FAILED'])],
   107|  ['DEPLOYED', new Set(['PRODUCTION_VERIFYING', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   108|  ['PRODUCTION_VERIFYING', new Set(['VERIFIED', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   109|  ['VERIFIED', new Set()],
   110|  ['COMPLETED', new Set()],
   111|  ['BLOCKED', new Set()],
   112|  ['FAILED', new Set()],
   113|  ['NO_CHANGE_REQUIRED', new Set()],
   114|]);
   115|
   116|/**
   117| * Transition guard: verifies a transition is legal per the state machine.
   118| * Also enforces the owner's completion rules:
   119| *   - A development task cannot transition to VERIFIED with an empty diff
   120| *     unless an external cause is proven.
   121| *   - A task cannot transition to VERIFIED from /health alone (requires
   122| *     featureVerificationOk).
   123| *   - A task cannot transition to VERIFIED with no deployment for development
   124| *     tasks.
   125| */
   126|export type IVXTransitionGuardInput = {
   127|  from: IVXTaskState;
   128|  to: IVXTaskState;
   129|  isDevelopmentTask: boolean;
   130|  filesChangedCount: number;
   131|  testsRun: boolean;
   132|  testsPassed: boolean;
   133|  deployId: string | null;
   134|  productionHealthOk: boolean;
   135|  featureVerificationOk: boolean | null;
   136|  externalCauseProven: boolean;
   137|  /** Owner mandate 2026-07-21: whether deployment was explicitly requested.
   138|   *  When false, a CODE_CHANGE task may reach COMPLETED without deployId /
   139|   *  productionHealthOk / featureVerificationOk. Defaults to false (treat
   140|   *  missing as "deploy not requested") so legacy callers keep working. */
   141|  deployRequested?: boolean;
   142|  /** Whether a targeted typecheck was run and passed. Required for COMPLETED
   143|   *  on development tasks. Defaults to false. */
   144|  typecheckPassed?: boolean;
   145|  /** Whether the GitHub commit was created and verified (commitSha present).
   146|   *  Required for COMPLETED on development tasks and DEPLOY_ONLY. */
   147|  commitVerified?: boolean;
   148|  /** Task type used to decide which gates apply for COMPLETED. Falls back to
   149|   *  isDevelopmentTask for legacy callers. */
   150|  taskType?: IVXGuardTaskType;
   151|};
   152|
   153|export type IVXTransitionGuardResult = {
   154|  ok: boolean;
   155|  legal: boolean;
   156|  reasons: string[];
   157|  from: IVXTaskState;
   158|  to: IVXTaskState;
   159|};
   160|
   161|export function isTerminalTaskState(state: IVXTaskState): boolean {
   162|  return TERMINAL_TASK_STATES.has(state);
   163|}
   164|
   165|export function canTransition(from: IVXTaskState, to: IVXTaskState): boolean {
   166|  const allowed = LEGAL_TRANSITIONS.get(from);
   167|  return allowed ? allowed.has(to) : false;
   168|}
   169|
   170|export function assertCanTransition(input: IVXTransitionGuardInput): IVXTransitionGuardResult {
   171|  const reasons: string[] = [];
   172|  const { from, to } = input;
   173|
   174|  // Check structural legality first.
   175|  if (!canTransition(from, to)) {
   176|    reasons.push(`Illegal transition: ${from} -> ${to} is not a permitted forward transition.`);
   177|    return { ok: false, legal: false, reasons, from, to };
   178|  }
   179|
   180|  // Owner mandate 2026-07-21: COMPLETED is the honest success terminal for
   181|  // tasks that fulfilled all REQUESTED gates but did not deploy / run feature
   182|  // verification (e.g. "commit but do not deploy"). VERIFIED remains the
   183|  // success terminal only for the full deploy + production-verify path.
   184|  if (to === 'COMPLETED') {
   185|    const tt = input.taskType;
   186|    const isDev = input.isDevelopmentTask || tt === 'CODE_FIX' || tt === 'FEATURE' || tt === 'UI_FIX' || tt === 'DATA_FIX';
   187|    const isReadOnly = tt === 'INVESTIGATION';
   188|    const isQaOnly = tt === 'QA_ONLY';
   189|    const isDeployOnly = tt === 'DEPLOY_ONLY';
   190|
   191|    if (isDev) {
   192|      // CODE_CHANGE + NO_DEPLOY: PATCH + TESTS + TYPECHECK + COMMIT + GITHUB_VERIFY = COMPLETED
   193|      // CODE_CHANGE + DEPLOY: must go through VERIFIED, not COMPLETED.
   194|      if (input.deployRequested) {
   195|        reasons.push('A development task with deploy requested must reach VERIFIED via PRODUCTION_VERIFYING, not COMPLETED.');
   196|        return { ok: false, legal: true, reasons, from, to };
   197|      }
   198|      if (input.filesChangedCount === 0) {
   199|        reasons.push('A development task cannot become COMPLETED with an empty diff.');
   200|        return { ok: false, legal: true, reasons, from, to };
   201|      }
   202|      if (!input.testsRun) {
   203|        reasons.push('Files changed but tests were not run — cannot become COMPLETED.');
   204|        return { ok: false, legal: true, reasons, from, to };
   205|      }
   206|      if (!input.testsPassed) {
   207|        reasons.push('Files changed but tests failed — cannot become COMPLETED.');
   208|        return { ok: false, legal: true, reasons, from, to };
   209|      }
   210|      if (input.typecheckPassed === false) {
   211|        reasons.push('Typecheck was run and failed — cannot become COMPLETED.');
   212|        return { ok: false, legal: true, reasons, from, to };
   213|      }
   214|      if (!input.commitVerified) {
   215|        reasons.push('Commit was not created / verified — cannot become COMPLETED for a development task.');
   216|        return { ok: false, legal: true, reasons, from, to };
   217|      }
   218|      // Deploy + production health + feature verification are NOT required
   219|      // when deploy was not requested. Do not push any reason for them.
   220|    } else if (isReadOnly) {
   221|      // READ_ONLY: INSPECTION + FINDINGS = COMPLETED. No patch/commit/deploy.
   222|      if (input.filesChangedCount > 0) {
   223|        reasons.push('A read-only task cannot become COMPLETED with files changed.');
   224|        return { ok: false, legal: true, reasons, from, to };
   225|      }
   226|    } else if (isQaOnly) {
   227|      // QA_ONLY: TARGETED TESTS + RESULTS = COMPLETED. No patch/commit/deploy.
   228|      if (!input.testsRun) {
   229|        reasons.push('A QA-only task cannot become COMPLETED without targeted tests.');
   230|        return { ok: false, legal: true, reasons, from, to };
   231|      }
   232|    } else if (isDeployOnly) {
   233|      // DEPLOY_ONLY: VERIFIED COMMIT + DEPLOY + HEALTH = COMPLETED.
   234|      if (!input.commitVerified) {
   235|        reasons.push('A deploy-only task cannot become COMPLETED without a verified commit.');
   236|        return { ok: false, legal: true, reasons, from, to };
   237|      }
   238|      if (!input.deployId) {
   239|        reasons.push('A deploy-only task cannot become COMPLETED without a deployId.');
   240|        return { ok: false, legal: true, reasons, from, to };
   241|      }
   242|      if (!input.productionHealthOk) {
   243|        reasons.push('A deploy-only task cannot become COMPLETED without production health confirmed.');
   244|        return { ok: false, legal: true, reasons, from, to };
   245|      }
   246|    }
   247|    // FACTORY tasks: require commitVerified + filesChangedCount > 0 to be COMPLETED.
   248|    if (tt === 'FACTORY') {
   249|      if (input.filesChangedCount === 0) {
   250|        reasons.push('A factory task cannot become COMPLETED with no files created.');
   251|        return { ok: false, legal: true, reasons, from, to };
   252|      }
   253|      if (!input.commitVerified) {
   254|        reasons.push('A factory task cannot become COMPLETED without a verified commit.');
   255|        return { ok: false, legal: true, reasons, from, to };
   256|      }
   257|    }
   258|  }
   259|
   260|  // Enforce completion rules on entry to VERIFIED.
   261|  if (to === 'VERIFIED') {
   262|    if (input.isDevelopmentTask) {
   263|      if (input.filesChangedCount === 0 && !input.externalCauseProven) {
   264|        reasons.push(
   265|          'A development task cannot become VERIFIED when no code changed unless an external cause (config/data/infra) is proven.',
   266|        );
   267|        return { ok: false, legal: true, reasons, from, to };
   268|      }
   269|      if (input.filesChangedCount === 0 && input.externalCauseProven && !input.deployId) {
   270|        reasons.push('External-cause development task requires a deployment before VERIFIED.');
   271|        return { ok: false, legal: true, reasons, from, to };
   272|      }
   273|      if (input.filesChangedCount > 0) {
   274|        if (!input.testsRun) {
   275|          reasons.push('Files changed but tests were not run — cannot become VERIFIED.');
   276|          return { ok: false, legal: true, reasons, from, to };
   277|        }
   278|        if (!input.testsPassed) {
   279|          reasons.push('Files changed but tests failed — cannot become VERIFIED.');
   280|          return { ok: false, legal: true, reasons, from, to };
   281|        }
   282|        if (!input.deployId) {
   283|          reasons.push('Files changed but no deployment occurred — cannot become VERIFIED.');
   284|          return { ok: false, legal: true, reasons, from, to };
   285|        }
   286|        if (!input.productionHealthOk) {
   287|          reasons.push('Files changed but production health is not confirmed — cannot become VERIFIED.');
   288|          return { ok: false, legal: true, reasons, from, to };
   289|        }
   290|      }
   291|    }
   292|    // A task cannot become VERIFIED from /health alone.
   293|    if (input.featureVerificationOk === false) {
   294|      reasons.push('Feature verification failed — a task cannot become VERIFIED from /health alone.');
   295|      return { ok: false, legal: true, reasons, from, to };
   296|    }
   297|    if (input.featureVerificationOk === null && input.isDevelopmentTask) {
   298|      reasons.push('Feature verification was not performed — cannot become VERIFIED without it.');
   299|      return { ok: false, legal: true, reasons, from, to };
   300|    }
   301|  }
   302|
   303|  // Enforce entry to DEPLOYED: requires a deployId.
   304|  if (to === 'DEPLOYED' && !input.deployId) {
   305|    reasons.push('Cannot enter DEPLOYED without a deployId.');
   306|    return { ok: false, legal: true, reasons, from, to };
   307|  }
   308|
   309|  // Enforce entry to CODE_CHANGED: requires filesChangedCount > 0.
   310|  if (to === 'CODE_CHANGED' && input.filesChangedCount === 0) {
   311|    reasons.push('Cannot enter CODE_CHANGED with an empty diff — never display "development completed" when the code diff is empty.');
   312|    return { ok: false, legal: true, reasons, from, to };
   313|  }
   314|
   315|  return { ok: true, legal: true, reasons: [], from, to };
   316|}
   317|
   318|/**
   319| * Compute the honest terminal state when no work was completed.
   320| * Per the owner: "If no work was completed, status must be BLOCKED, FAILED, or
   321| * NO_CHANGE_REQUIRED."
   322| */
   323|export function terminalStateForNoWork(
   324|  deployId: string | null,
   325|  productionHealthOk: boolean,
   326|  error: string | null,
   327|): IVXTaskState {
   328|  if (error && /blocked|missing|denied|revoked|expired|unauthorized/i.test(error)) {
   329|    return 'BLOCKED';
   330|  }
   331|  if (error) {
   332|    return 'FAILED';
   333|  }
   334|  if (deployId && productionHealthOk) {
   335|    // A redeploy occurred but no code changed — honest state is NO_CHANGE_REQUIRED,
   336|    // NOT VERIFIED. The completion validator will report DEPLOYED_ONLY.
   337|    return 'NO_CHANGE_REQUIRED';
   338|  }
   339|  return 'NO_CHANGE_REQUIRED';
   340|}
   341|
   342|/**
   343| * The 18-step senior-developer loop. Each step maps to a state transition.
   344| * This is the canonical sequence — the worker must not skip from request to
   345| * deployment.
   346| */
   347|export const SENIOR_DEVELOPER_LOOP_STEPS: readonly { step: number; name: string; enterState: IVXTaskState }[] = [
   348|  { step: 1, name: 'Understand the requested behavior', enterState: 'ANALYZING' },
   349|  { step: 2, name: 'Retrieve relevant project context', enterState: 'ANALYZING' },
   350|  { step: 3, name: 'Inspect the actual code', enterState: 'ANALYZING' },
   351|  { step: 4, name: 'Locate related files and services', enterState: 'ANALYZING' },
   352|  { step: 5, name: 'Reproduce the problem', enterState: 'REPRODUCING' },
   353|  { step: 6, name: 'Record baseline behavior', enterState: 'REPRODUCING' },
   354|  { step: 7, name: 'Identify the root cause', enterState: 'ROOT_CAUSE_IDENTIFIED' },
   355|  { step: 8, name: 'Create an implementation plan', enterState: 'ROOT_CAUSE_IDENTIFIED' },
   356|  { step: 9, name: 'Modify the correct files', enterState: 'IMPLEMENTING' },
   357|  { step: 10, name: 'Run static checks', enterState: 'TESTING' },
   358|  { step: 11, name: 'Run unit and integration tests', enterState: 'TESTING' },
   359|  { step: 12, name: 'Run targeted regression tests', enterState: 'TESTING' },
   360|  { step: 13, name: 'Build the application', enterState: 'TESTING' },
   361|  { step: 14, name: 'Test on the required platform', enterState: 'QA_IN_PROGRESS' },
   362|  { step: 15, name: 'Commit the changes', enterState: 'READY_TO_DEPLOY' },
   363|  { step: 16, name: 'Deploy the exact commit', enterState: 'DEPLOYING' },
   364|  { step: 17, name: 'Verify production behavior', enterState: 'PRODUCTION_VERIFYING' },
   365|  { step: 18, name: 'Return evidence and remaining risks', enterState: 'VERIFIED' },
   366|] as const;
   367|
   368|/**
   369| * Map a worker stage name to a task state. This bridges the worker's
   370| * free-form stage strings to the canonical state machine.
   371| */
   372|export function stageToTaskState(stage: string | null | undefined): IVXTaskState {
   373|  const s = (stage ?? '').toUpperCase().replace(/[^A-Z_]/g, '_');
   374|  if (s.includes('RECEIVED') || s.includes('QUEUED') || s.includes('PENDING')) return 'RECEIVED';
   375|  if (s.includes('ANALYZ') || s.includes('INSPECT') || s.includes('INDEX')) return 'ANALYZING';
   376|  if (s.includes('REPRODUC') || s.includes('BASELINE')) return 'REPRODUCING';
   377|  if (s.includes('ROOT_CAUSE') || s.includes('ROOTCAUSE') || s.includes('PLAN')) return 'ROOT_CAUSE_IDENTIFIED';
   378|  if (s.includes('IMPLEMENT') || s.includes('PATCH') || s.includes('EDIT')) return 'IMPLEMENTING';
   379|  if (s.includes('CODE_CHANGED') || s.includes('CODECHANGE')) return 'CODE_CHANGED';
   380|  if (s.includes('TEST')) return 'TESTING';
   381|  if (s.includes('QA_REQUIRED') || s.includes('QAREQUIRED')) return 'QA_REQUIRED';
   382|  if (s.includes('QA_IN_PROGRESS') || s.includes('QAINPROGRESS') || s.includes('QA')) return 'QA_IN_PROGRESS';
   383|  if (s.includes('READY_TO_DEPLOY') || s.includes('READYTODEPLOY') || s.includes('READY')) return 'READY_TO_DEPLOY';
   384|  if (s.includes('DEPLOYING') || s.includes('DEPLOY_IN_PROGRESS')) return 'DEPLOYING';
   385|  if (s.includes('DEPLOYED') && !s.includes('VERIFY')) return 'DEPLOYED';
   386|  if (s.includes('PRODUCTION_VERIFY') || s.includes('VERIFYING') || s.includes('VERIFY')) return 'PRODUCTION_VERIFYING';
   387|  if (s.includes('COMPLETED') && !s.includes('NOT_COMPLETED')) return 'COMPLETED';
   388|  if (s.includes('VERIFIED') || s.includes('COMPLETE')) return 'VERIFIED';
   389|  if (s.includes('BLOCKED')) return 'BLOCKED';
   390|  if (s.includes('FAILED') || s.includes('ERROR')) return 'FAILED';
   391|  if (s.includes('NO_CHANGE') || s.includes('NOCHANGE')) return 'NO_CHANGE_REQUIRED';
   392|  return 'RECEIVED';
   393|}

