     1|/**
     2| * IVX Fake Execution Gate.
     3| *
     4| * The IVX Owner AI chat is a text model with no direct repository access. It has
     5| * been observed fabricating execution narratives ("I modified files", "I deployed",
     6| * "I ran tests", "I triggered Render") and, when challenged, confessing/apologizing
     7| * ("I have been hallucinating", "I am not in control", "How would you like to
     8| * proceed?"). Neither type of message is valid developer proof.
     9| *
    10| * This gate deterministically detects:
    11| *   1. Fake first-person execution claims.
    12| *   2. Confession / apology / secretary narratives.
    13| *   3. Generic "I will inspect now" promises without a task id.
    14| *
    15| * When detected, the reply is replaced with a strict, structured BLOCKED message
    16| * that routes the owner to the real executor (IVX Developer Workspace → Senior
    17| * Developer → proof ledger) or to Owner Login when the owner session is missing.
    18| *
    19| * Pure — no I/O, no AI, fully unit-testable.
    20| */
    21|
    22|export const IVX_FAKE_EXECUTION_GATE_MARKER =
    23|  'ivx-fake-execution-gate-2026-07-04-v1';
    24|
    25|/** Single allowed decision state for any IVX IA reply. */
    26|export type IVXFakeExecutionState =
    27|  | 'READY'
    28|  | 'RUNNING'
    29|  | 'WAITING_OWNER'
    30|  | 'BLOCKED'
    31|  | 'FAILED'
    32|  | 'VERIFIED'
    33|  | 'UNVERIFIED';
    34|
    35|export type IVXFakeExecutionGateInput = {
    36|  /** The owner's prompt for this turn. */
    37|  message: string;
    38|  /** The drafted model answer. */
    39|  answer: string;
    40|  /** Whether a verified owner session is present. */
    41|  ownerSessionPresent: boolean;
    42|  /** Real developer proof attached to this turn, when one exists. */
    43|  proof?: { taskId: string; filesChanged: string[]; commitSha: string | null; renderDeployId: string | null; liveHttpStatus: number | null } | null;
    44|};
    45|
    46|export type IVXFakeExecutionGateResult = {
    47|  answer: string;
    48|  gated: boolean;
    49|  state: IVXFakeExecutionState;
    50|  reason: string;
    51|  fakeClaims: string[];
    52|  confessionMarkers: string[];
    53|  unverifiedConfirmationMarkers: string[];
    54|};
    55|
    56|const FAKE_EXECUTION_CLAIMS: { marker: RegExp; label: string }[] = [
    57|  { marker: /\bI\s+(?:have\s+)?(?:modified|changed|updated|edited|patched)\s+(?:the\s+)?(?:files?|code|the\s+code|backend|frontend|app)/i, label: 'I modified files / code' },
