    46|/**
    47| * Leasing: a worker lease grants a single worker exclusive ownership of a job
    48| * for a bounded duration. If the worker dies, the lease expires and another
    49| * worker may claim the job. This prevents two workers from processing the
    50| * same job simultaneously.
    51| */
    52|export type IVXWorkerLease = {
    53|  jobId: string;
    54|  workerId: string;
    55|  acquiredAt: string;
    56|  expiresAt: string;
    57|  heartbeatAt: string;
    58|};
    59|
    60|export type IVXLeaseStore = {
    61|  acquire(jobId: string, workerId: string, ttlMs: number): IVXWorkerLease | null;
    62|  renew(jobId: string, workerId: string, ttlMs: number): IVXWorkerLease | null;
    63|  release(jobId: string, workerId: string): boolean;
    64|  current(jobId: string): IVXWorkerLease | null;
    65|};
    66|
    67|/**
    68| * In-memory lease store (sufficient for single-instance Render; for
    69| * multi-instance, swap for a Redis-backed store).
    70| */
    71|export function createInMemoryLeaseStore(): IVXLeaseStore {
    72|  const leases = new Map<string, IVXWorkerLease>();
    73|
    74|  function now(): string {
    75|    return new Date().toISOString();
    76|  }
    77|
    78|  function expired(lease: IVXWorkerLease): boolean {
    79|    return new Date(lease.expiresAt).getTime() < Date.now();
    80|  }
    81|
    82|  return {
    83|    acquire(jobId, workerId, ttlMs) {
    84|      const existing = leases.get(jobId);
    85|      if (existing && !expired(existing) && existing.workerId !== workerId) {
    86|        return null; // held by another worker
    87|      }
    88|      const lease: IVXWorkerLease = {
    89|        jobId,
    90|        workerId,
    91|        acquiredAt: now(),
    92|        expiresAt: new Date(Date.now() + ttlMs).toISOString(),
    93|        heartbeatAt: now(),
    94|      };
    95|      leases.set(jobId, lease);
    96|      return lease;
    97|    },
    98|    renew(jobId, workerId, ttlMs) {
    99|      const existing = leases.get(jobId);
   100|      if (!existing || existing.workerId !== workerId) {
   101|        return null;
   102|      }
   103|      const lease: IVXWorkerLease = {
   104|        ...existing,
   105|        expiresAt: new Date(Date.now() + ttlMs).toISOString(),
   106|        heartbeatAt: now(),
   107|      };
   108|      leases.set(jobId, lease);
   109|      return lease;
   110|    },
   111|    release(jobId, workerId) {
   112|      const existing = leases.get(jobId);
   113|      if (!existing || existing.workerId !== workerId) {
   114|        return false;
   115|      }
   116|      leases.delete(jobId);
   117|      return true;
   118|    },
   119|    current(jobId) {
   120|      const existing = leases.get(jobId);
   121|      if (!existing) return null;
   122|      if (expired(existing)) {
   123|        leases.delete(jobId);
   124|        return null;
   125|      }
   126|      return existing;
   127|    },
   128|  };
