   303|// ---------- AI Execution Stages (replaces simple typing indicator) ----------
   304|
   305|export type AIExecutionStage =
   306|  | 'idle'
   307|  | 'uploading_attachment'
   308|  | 'delivering_message'
   309|  | 'searching_repo'
   310|  | 'reading_files'
   311|  | 'inspecting_functions'
   312|  | 'running_checks'
   313|  | 'preparing_patch'
   314|  | 'awaiting_provider'
   315|  | 'streaming_response'
   316|  | 'blocked_waiting'
   317|  | 'done';
   318|
   319|export function resolveAIExecutionStage(input: {
   320|  attachmentPending: boolean;
   321|  sendPending: boolean;
   322|  aiReplyPending: boolean;
   323|  requestStage: string;
   324|  source: string;
   325|  failureClass: string;
   326|  hasVisibleResponseText: boolean;
   327|}): AIExecutionStage {
   328|  if (input.attachmentPending) return 'uploading_attachment';
   329|  if (input.sendPending) return 'delivering_message';
   330|  if (!input.aiReplyPending) return input.hasVisibleResponseText ? 'done' : 'idle';
   331|
   332|  const stage = input.requestStage;
   333|  const failure = input.failureClass;
   334|
   335|  if (failure && failure !== 'none' && failure !== 'pending') {
   336|    return 'blocked_waiting';
   337|  }
   338|  if (stage === 'request_started' || stage === 'proxy_status_ok') return 'searching_repo';
   339|  if (stage === 'tool_code_read' || stage === 'reading_files') return 'reading_files';
   340|  if (stage === 'tool_code_search') return 'searching_repo';
   341|  if (stage === 'tool_inspect' || stage === 'inspecting_functions') return 'inspecting_functions';
   342|  if (stage === 'tool_test_run' || stage === 'running_checks') return 'running_checks';
   343|  if (stage === 'patch_generate' || stage === 'preparing_patch') return 'preparing_patch';
   344|  if (stage === 'verifying_result' || stage === 'response_ok') return 'streaming_response';
   345|  if (stage === 'streaming' || stage === 'stage:stream' || stage === 'sse_start') return 'streaming_response';
   346|  if (input.source === 'provider_fallback') return 'awaiting_provider';
   347|  return 'awaiting_provider';
