   369|const TECHNICAL_PROOF_REGEX = /\b(file|line|function|patch|stack|error|crash|fix|diagnos(?:e|tics)|audit|proof|deploy|rollback|incident|supabase|render|otel|trace|repo|grep|search|typecheck|lint|e2e|maestro|playwright|provider|fallback|sse|owner ai|owner-ai|chat\.tsx)\b/i;
   370|
   371|export function shouldDefaultToProofMode(prompt: string): boolean {
   372|  if (!prompt || prompt.length < 4) return false;
   373|  return TECHNICAL_PROOF_REGEX.test(prompt);
