    default:
      return {
        requiresCodeChange: false,
        requiresTests: false,
        requiresDeployment: false,
        requiresDeviceQA: false,
        requiresFeatureVerification: false,
        requiresConfigurationBefore: false,
        requiresConfigurationAfter: false,
      };
  }
}

